          </button>
        </div>
      )}

      <ModalSelectToken
        isVisible={showModalSelectToken}
        onClose={() => SetShowModalSelectToken(false)}
        baseTokens={TOKENS}
        onDataSend={handleSelectedToken}
        selectedToken={selectedToken}
      />
    </>
  );
}

export default App;

